test('verified admin is a token role or subject, never an email list or empty config', () => {
  assert.equal(isVerifiedAdmin({}, { email: 'tony.walteur@gmail.com', roles: [] }), false);
  assert.equal(isVerifiedAdmin({ ADMIN_EMAILS: 'tony.walteur@gmail.com' }, { email: 'tony.walteur@gmail.com' }), false);
  assert.equal(isVerifiedAdmin({ ATLAS_ADMIN_ROLES: '', ATLAS_ADMIN_SUBJECTS: '' }, { roles: ['ATLAS.Admin'], sub: 'user-1' }), false);
  assert.equal(isVerifiedAdmin({}, { roles: ['ATLAS.Admin'], sub: 'user-1' }), false, 'a missing admin config grants nobody');
  assert.equal(isVerifiedAdmin({ ATLAS_ADMIN_ROLES: 'ATLAS.Admin' }, { roles: ['ATLAS.Admin'], sub: 'user-1' }), true);
  assert.equal(isVerifiedAdmin({ ATLAS_ADMIN_SUBJECTS: 'user-1' }, { sub: 'user-1', roles: [] }), true);
  assert.equal(elevatedRole({}, { roles: ['ATLAS.Presales'] }), null);
  assert.equal(elevatedRole({ ATLAS_PRESALES_ROLES: 'ATLAS.Presales' }, { roles: ['ATLAS.Presales'] }), 'presales');
  assert.equal(elevatedRole({ ATLAS_REVIEWER_ROLES: 'ATLAS.Review' }, { roles: ['ATLAS.Review'] }), 'reviewer');
  assert.equal(elevatedRole({ ATLAS_ADMIN_ROLES: 'ATLAS.Admin', ATLAS_PRESALES_ROLES: 'ATLAS.Presales' }, { roles: ['ATLAS.Admin', 'ATLAS.Presales'] }), 'admin');
  assert.equal(privilegeReadiness({}).ok, false);
  assert.match(privilegeReadiness({}).errors.join(' '), /grants nobody/);
  assert.equal(privilegeReadiness({ ATLAS_TENANT_ISOLATION: 'local-synthetic' }).mode, 'local-synthetic');
  assert.equal(privilegeReadiness({ ATLAS_ADMIN_SUBJECTS: 'user-1', ATLAS_PRESALES_ROLES: 'ATLAS.Presales', ATLAS_REVIEWER_ROLES: 'ATLAS.Reviewer' }).ok, true);
  assert.equal(devIdentityEnabled({}), false);
  assert.equal(devIdentityEnabled({ ATLAS_DEV_IDENTITY: '1' }), false);
  assert.equal(devIdentityEnabled({ ATLAS_DEV_IDENTITY: '1', ATLAS_TENANT_ISOLATION: 'local-synthetic' }), true);
});

test('non-admins need trusted manager and presales; checkbox and typed email do not publish or grant access', async () => {
  const l = lib();
  const saved = await l.upsert(OWNER, { localId: 'p', reference: ref() });
  await l.review(OWNER, saved.id);
  l.setState(l.row(saved.id), { ...l.row(saved.id).state, quality: { status: 'ready', score: 90 } }, 'test', 'reviewed', '');
  assert.notEqual(l.get(OWNER, saved.id).status, 'published');
  assert.throws(() => l.get(MGR, saved.id), /not found/);
  assert.throws(() => l.get({ email: 'jo@example.test', role: 'user', tenant: 'tenant-a' }, saved.id), /not found/);
  assert.throws(() => l.validate(MGR, saved.id, { lane: 'manager', decision: 'validate' }), /not found/);
  l.bindTrust(SYS, { owner: OWNER.email, email: MGR.email, source: 'directory', tenant: 'tenant-a' });
  assert.equal(l.validate(MGR, saved.id, { lane: 'manager', decision: 'validate' }).status, 'awaiting_validation');
  assert.throws(() => l.validate(MGR, saved.id, { lane: 'presales', decision: 'validate' }), /bid\/pre-sales/);
  assert.equal(l.validate(PRE, saved.id, { lane: 'presales', decision: 'validate' }).status, 'published');
  assert.throws(() => l.get(OTHER_TENANT, saved.id), /not found/);
  assert.throws(() => l.exportAll(PRE), /verified admin/);
  assert.equal(l.exportAll(ADMIN).references.length, 1);
  assert.equal(l.exportAll(OTHER_TENANT).references.length, 0);
  assert.ok(l.rows("SELECT action FROM audit WHERE action = 'admin export'").length >= 1);
});

test('verified admin bypass is explicit, audited, and a test copy is not public', async () => {
  const l = lib();
  const saved = await l.upsert(OWNER, { localId: 'p', reference: ref() });
  await l.review(OWNER, saved.id);
  l.setState(l.row(saved.id), { ...l.row(saved.id).state, quality: { status: 'ready', score: 90 } }, 'test', 'reviewed', '');
  await assert.rejects(l.adminPublish(MGR, saved.id, { test: true }), /verified admin/);
  const testCopy = await l.adminPublish(ADMIN, saved.id, { test: true });
  assert.equal(testCopy.status, 'admin_test');
  assert.throws(() => l.get({ email: 'reader@example.test', role: 'user', tenant: 'tenant-a' }, saved.id), /not found/);
  assert.ok(l.get(ADMIN, saved.id).audit.some(a => a.action === 'admin-publish-bypass' && a.detail === 'test'));
  const live = await l.upsert(ADMIN, { localId: 'q', reference: { ...ref(), title: 'Second alias' } });
  await l.review(ADMIN, live.id);
  l.setState(l.row(live.id), { ...l.row(live.id).state, quality: { status: 'ready', score: 90 } }, 'test', 'reviewed', '');
  const published = await l.adminPublish(ADMIN, live.id, { test: false });
  assert.equal(published.status, 'published');
  assert.equal(l.get({ email: 'reader@example.test', role: 'user', tenant: 'tenant-a' }, live.id).access, 'public');
});

test('dashboard metrics keep missing tokens missing and price only configured rates', async () => {
  const l = lib();
  await recordUsage(l, ADMIN, { kind: 'usage', feature: 'voice', outcome: 'ok', latencyMs: 40, tokenStatus: 'actual', tokensIn: 10, tokensOut: 4, model: 'local' });
  await recordUsage(l, ADMIN, { kind: 'error', feature: 'voice', outcome: 'error', errorClass: 'timeout', tokenStatus: 'missing' });
  const bare = queryMetrics(l, ADMIN, {}, {});
  assert.equal(bare.tokens.actualIn, 10);
  assert.equal(bare.tokens.missing, 1);
  assert.equal(bare.estimatedCost, null);
  assert.equal(bare.costStatus, 'not-configured');
  const priced = queryMetrics(l, ADMIN, { ATLAS_TOKEN_RATE_IN: 0.000002, ATLAS_TOKEN_RATE_OUT: 0.000008, ATLAS_COST_CURRENCY: 'USD' }, {});
  assert.equal(priced.estimatedCost.currency, 'USD');
  assert.equal(priced.estimatedCost.basis, 'configured-unit-rate');
  assert.ok(priced.estimatedCost.amount > 0);
  const call = (who, path) => libraryRoutes(new Request('https://atlas.test' + path, { headers: { 'x-atlas-user': who.email, 'x-atlas-role': who.role, 'x-atlas-tenant': who.tenant } }), l);
  assert.equal((await call(OWNER, '/api/library/admin/metrics')).status, 403);
  assert.equal((await call(ADMIN, '/api/library/admin/metrics')).status, 200);
  assert.equal((await call(OWNER, '/api/library/admin/export')).status, 403);
});

