  l.sql.exec("INSERT INTO confirmation_requests (id, ref_id, revision, kind, to_email, manager_source, claim_ids, status, created_by, created_at, expires_at, tenant) VALUES ('a-late', ?, 1, 'manager', 'sam@example.test', 'staffing', '[]', 'open', 'ada@example.test', '2026-10-15T00:00:00.000Z', '2026-12-01T00:00:00.000Z', ?)", story.id, A);
  const samA = { email: 'sam@example.test', mail: 'sam@example.test', role: 'user', tenant: A, tenantEnforced: true };
