  const storyB = await l.upsert(owner(B), { localId: 'm2', reference: other });
  await assert.rejects(l.merge(reviewer(A), { keep: storyA.id, merge: storyB.id }), /not found/);
  assert.equal(l.row(storyB.id).merged_into, null);
  l.withdraw(owner(B), storyB.id, { note: 'pause' });
  await assert.rejects(async () => { l.reinstate(reviewer(A), storyB.id); }, e => e.status === 404);
  assert.equal(l.row(storyB.id).state.withdrawn, true);
  await l.index(storyA.id);
  assert.equal((l.row(storyB.id).state.duplicates || []).some(d => d.id === storyA.id), false);
  await assert.rejects(async () => { l.invite('rev@example.test', { email: 'ada@example.test', reason: 'manual', projectId: 'PX', tenant: B }, reviewer(A)); }, e => e.status === 403);
  assert.equal(l.rows("SELECT COUNT(*) AS n FROM invitations WHERE project_id = 'PX'")[0].n, 0);
  const stamped = l.invite('rev@example.test', { email: 'ada@example.test', reason: 'manual', projectId: 'PY' }, reviewer(A));
  assert.equal(stamped.tenant, A);
  ensureOutreach(l);
  l.sql.exec("INSERT INTO outreach (id, kind, subject_id, channel, to_email, status, reason, payload, created_at, tenant) VALUES ('o-b', 'interview_invite', 'sb', 'email_draft', 'ada@example.test', 'pending_approval', '', '{}', '2026-11-08T00:00:00.000Z', ?)", B);
  l.sql.exec("INSERT INTO outreach (id, kind, subject_id, channel, to_email, status, reason, payload, created_at, tenant) VALUES ('o-a', 'interview_invite', ?, 'teams', 'ada@example.test', 'pending_approval', '', '{}', '2026-11-08T00:00:00.000Z', ?)", stamped.id, A);
  l.sql.exec("INSERT INTO teams_conversations (subject, aad_object_id, tenant_id, teams_user_id, conversation_id, service_url, email, status, updated_at) VALUES ('person', 'oid', ?, 'tu', 'conv', 'https://teams.example/', 'ada@example.test', 'active', '2026-11-08T00:00:00.000Z')", B);
  let sent = 0;
  l.services.teams = { async send() { sent += 1; return { id: 'm1' }; } };
  const seen = await outreachRoutes({ method: 'GET', parts: ['outreach'], user: reviewer(A), lib: l, url: new URL('https://atlas.test/api/library/outreach') });
  assert.deepEqual(seen.body.items.map(x => x.id), ['o-a']);
  await assert.rejects(async () => { await outreachRoutes({ method: 'POST', parts: ['outreach', 'o-b'], user: reviewer(A), lib: l, body: { action: 'dismiss' } }); }, e => e.status === 404);
  const delivered = await outreachRoutes({ method: 'POST', parts: ['outreach', 'o-a'], user: reviewer(A), lib: l, body: { action: 'approve' } });
  assert.equal(delivered.body.item.status, 'blocked_external');
  assert.equal(sent, 0);
