  assert.equal(seen.audit.some(a => a.action === 'possible duplicate' && a.detail === ''), true);
  assert.equal(l.rows("SELECT detail FROM audit WHERE id = ? AND action = 'possible duplicate'", mine.id)[0].detail, 'Hidden title');
