  assert.equal(l.rows("SELECT COUNT(*) AS n FROM invitations WHERE reference_id = ?", hidden.id)[0].n, 0);
  assert.equal(l.rows('SELECT COUNT(*) AS n FROM audit WHERE id = ?', hidden.id)[0].n, beforeAudit);
