test('invitation and trust follow verified subject and mail aliases', async () => {
  const l = lib();
  const A = '11111111-1111-4111-8111-111111111111', B = '22222222-2222-4222-8222-222222222222';
  const subject = A + ':aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
  const entra = { email: subject, mail: 'ada@example.test', role: 'user', tenant: A, tenantEnforced: true };
  const reviewer = { email: 'rev@example.test', mail: 'rev@example.test', role: 'reviewer', tenant: A, tenantEnforced: true };
  const story = await l.upsert(entra, { localId: 'alias-story', reference: ref() });
  const invited = l.invite(reviewer.email, { email: 'ada@example.test', reason: 'manual', projectId: 'ALIAS', referenceId: story.id }, reviewer);
  assert.equal(l.invitations(entra).some(i => i.id === invited.id), true);
  assert.equal(l.invitations({ email: subject, role: 'user', tenant: A, tenantEnforced: true }).some(i => i.id === invited.id), false);
  assert.equal(l.invitations({ ...entra, tenant: B }).length, 0);
  const updated = l.updateInvitation(entra, invited.id, { action: 'dismiss' });
  assert.equal(updated.status, 'dismissed');
  l.bindTrust({ role: 'system', tenant: A, tenantEnforced: true }, { owner: subject, email: 'sam@example.test', source: 'directory', tenant: A, tenantEnforced: true });
  const manager = { email: 'sam@example.test', mail: 'sam@example.test', role: 'user', tenant: A, tenantEnforced: true };
  assert.equal(l.canManagerApprove(l.row(story.id), manager), true);
  assert.equal(l.canManagerApprove(l.row(story.id), { email: subject, role: 'user', tenant: A, tenantEnforced: true }), false);
  assert.equal(l.canManagerApprove(l.row(story.id), { ...manager, tenant: B }), false);
  const hidden = await l.upsert({ email: 'kim@example.test', mail: 'kim@example.test', role: 'user', tenant: A, tenantEnforced: true }, { localId: 'hidden-ref', reference: ref() });
  const open = l.invite(reviewer.email, { email: 'ada@example.test', reason: 'manual', projectId: 'KEEP', referenceId: hidden.id }, reviewer);
  const before = l.row(hidden.id).state;
  await assert.rejects(async () => { l.updateInvitation(entra, open.id, { action: 'done' }); }, e => e.status === 404);
  assert.equal(l.rows('SELECT status, reference_id FROM invitations WHERE id = ?', open.id)[0].status, 'open');
  assert.equal(JSON.stringify(l.row(hidden.id).state), JSON.stringify(before));
});

