test('a staffing replacement revokes only the obsolete staffing grant', async () => {
  const l = lib();
  const A = '11111111-1111-4111-8111-111111111111';
  const B = '22222222-2222-4222-8222-222222222222';
  const reviewer = { email: 'rev@example.test', mail: 'rev@example.test', role: 'reviewer', tenant: A, tenantEnforced: true };
  const consultant = { email: 'ada@example.test', mail: 'ada@example.test', role: 'user', tenant: A, tenantEnforced: true };
  const story = await l.upsert(consultant, { localId: 'grant-story', reference: ref() });
  const mgr = email => ({ email, mail: email, role: 'user', tenant: A, tenantEnforced: true });
  const csv = (project, email) => `project_id,consultant_email,manager_email,manager_name,project_title,end_date\n${project},ada@example.test,${email},Mgr,Pilot,2026-11-01\n`;
  const imported = body => outreachRoutes({ method: 'POST', parts: ['staffing', 'import'], user: reviewer, lib: l, url: new URL('https://atlas.test/api/library/staffing/import'), body });
  assert.equal((await imported({ csv: csv('PRJ-SYN', 'sam-a@example.test') })).body.trustSkipped, 0);
  assert.equal(l.canManagerApprove(l.row(story.id), mgr('sam-a@example.test')), true);
  assert.equal(l.get(mgr('sam-a@example.test'), story.id).access, 'full');
  assert.equal((await imported({ csv: csv('PRJ-SYN', 'sam-b@example.test') })).body.trustSkipped, 0);
  assert.equal(l.canManagerApprove(l.row(story.id), mgr('sam-a@example.test')), false);
  assert.throws(() => l.get(mgr('sam-a@example.test'), story.id), /not found/);
  assert.equal(l.canManagerApprove(l.row(story.id), mgr('sam-b@example.test')), true);
  assert.equal(l.get(mgr('sam-b@example.test'), story.id).access, 'full');
  l.bindTrust({ email: 'directory', role: 'system', tenant: B, tenantEnforced: true }, { owner: 'ada@example.test', email: 'sam-a@example.test', source: 'staffing', tenant: B, tenantEnforced: true });
  l.bindTrust({ email: 'directory', role: 'system', tenant: A, tenantEnforced: true }, { owner: 'ada@example.test', email: 'noor@example.test', source: 'directory', tenant: A, tenantEnforced: true });
  l.sql.exec("INSERT INTO manager_trust (owner, email, source, tenant, at) VALUES ('ada@example.test', 'legacy@example.test', '', ?, '2026-11-08T00:00:00.000Z')", A);
  const otherStory = await l.upsert(consultant, { localId: 'other-project', reference: { ...ref(), details: { ...ref().details, projectId: 'PRJ-OTHER' } } });
  assert.equal((await imported({ csv: csv('PRJ-OTHER', 'sam-a@example.test') + 'PRJ-SYN,ada@example.test,sam-b@example.test,Mgr,Pilot,2026-11-01\n' })).body.staffed, 2);
  assert.equal(l.canManagerApprove(l.row(story.id), mgr('sam-a@example.test')), false);
  assert.equal(l.canManagerApprove(l.row(otherStory.id), mgr('sam-a@example.test')), true);
  assert.equal(l.canManagerApprove(l.row(otherStory.id), mgr('sam-b@example.test')), false);
  assert.equal(l.canManagerApprove(l.row(story.id), mgr('noor@example.test')), true);
  assert.equal(l.canManagerApprove(l.row(story.id), mgr('legacy@example.test')), false);
  assert.equal(l.rows("SELECT email FROM manager_trust WHERE lower(tenant) = ? AND lower(email) = 'sam-a@example.test'", B).length, 1);
  assert.equal(l.rows("SELECT source FROM manager_trust WHERE lower(email) = 'legacy@example.test'")[0].source, '');
  const stuck = lib();
  const stuckStory = await stuck.upsert(consultant, { localId: 'stuck', reference: ref() });
  assert.equal((await outreachRoutes({ method: 'POST', parts: ['staffing', 'import'], user: reviewer, lib: stuck, url: new URL('https://atlas.test/api/library/staffing/import'), body: { csv: csv('PRJ-SYN', 'sam-a@example.test') } })).body.trustSkipped, 0);
  const orig = stuck.sql.exec.bind(stuck.sql);
  stuck.sql.exec = (q, ...p) => { if (String(q).startsWith('DELETE FROM manager_trust')) throw new Error('disk'); return orig(q, ...p); };
  const failed = await outreachRoutes({ method: 'POST', parts: ['staffing', 'import'], user: reviewer, lib: stuck, url: new URL('https://atlas.test/api/library/staffing/import'), body: { csv: csv('PRJ-SYN', 'sam-b@example.test') } });
  assert.equal(failed.body.trustSkipped, 1);
  assert.equal(failed.body.staffed, 0);
  assert.equal(failed.body.invited, 0);
  assert.equal(stuck.rows("SELECT manager_email FROM staffing WHERE lower(project_id) = 'prj-syn'")[0].manager_email, 'sam-a@example.test');
  assert.deepEqual(stuck.rows('SELECT email FROM manager_trust ORDER BY email').map(r => r.email), ['sam-a@example.test']);
  assert.equal(stuck.canManagerApprove(stuck.row(stuckStory.id), mgr('sam-a@example.test')), true);
  assert.equal(stuck.canManagerApprove(stuck.row(stuckStory.id), mgr('sam-b@example.test')), false);
});

