  assert.equal(l.canManagerApprove(l.row(bothStory.id), mgr('new-both@example.test')), true);
  plant('PRJ-BARE', 'Dee@example.test', upperA, 'kept@example.test');
  l.bindTrust({ email: 'staffing-csv', role: 'system', tenant: A, tenantEnforced: true }, { owner: 'dee@example.test', email: 'kept@example.test', source: 'staffing', tenant: A, tenantEnforced: true });
  const bare = await imported(header + 'prj-bare,dee@example.test,,,Pilot,2026-12-01\n');
  assert.equal(bare.body.staffed, 1);
  assert.equal(bare.body.blocked.length, 0);
