  l.sql.exec("INSERT INTO outreach (id, kind, subject_id, channel, to_email, status, reason, payload, aad_object_id, created_at, tenant, directory_tenant, conversation_id) VALUES ('out-conv', 'interview_invite', 'inv-conv', 'teams', 'ada@example.test', 'sent', '', '{}', ?, '2026-11-08T00:00:00.000Z', ?, ?, 'conv-right')", oid, A, directory);
  l.sql.exec("INSERT INTO teams_conversations (subject, aad_object_id, tenant_id, teams_user_id, conversation_id, service_url, email, status, updated_at) VALUES (?, ?, ?, 'tu', 'conv-right', 'https://smba.example/', 'ada@example.test', 'active', '2026-11-08T00:00:00.000Z')", directory + ':' + oid, oid, directory);
  const bot = { email: 'teams-bot', role: 'system', tenant: A, tenantEnforced: true };
  const wrong = await teamsSystem({ lib: l, user: bot, body: { kind: 'action', activityId: 'conv-wrong', tenantId: directory, aadObjectId: oid, conversationId: 'conv-other', verb: 'decline', outreachId: 'out-conv' } });
